wire_blocks.exact_definition:
type Id=string; type Key=string; type BusinessRef={owner:Key;id:Key;version:Key}; type Ref=BusinessRef;
type Link=string; type Instant=string; type Hash=string; type RV=string;
type Digest={algorithm:'sha256';canonicalizationVersion:Key;value:Hash};
type Scope={environmentId:Key;tenantId:Id};
type Subject={businessOwner:Key;bizType:Key;subjectKind:Key;subjectId:Key;businessRevision:Key;contentDigest:Digest};
type Policy={ref:Ref;version:Key;digest:Digest};
type ActorEvidence =
 {kind:'HUMAN_TASK';decisionPrincipalId:Id;actualHandlerId:Id;onBehalfOfId:Id|null;
  taskId:Id;roleKey:Key;grantId:Id|null;grantRevision:Key|null;
  permissionEvidenceRef:Ref;sodEvidenceRef:Ref;occurredAt:Instant}
 |{kind:'SYSTEM_EXECUTION';serviceId:Key;executionId:Id;trigger:'TIMEOUT'|'RESUME'|'RULE';
  executionAuthorizationRef:Ref;policyRef:Ref;occurredAt:Instant}
 |{kind:'SUBMITTER_WITHDRAWAL';withdrawCommandId:Id;requesterId:Id;actualHandlerId:Id;
  onBehalfOfId:Id|null;grantId:Id|null;grantRevision:Key|null;
  ownerWithdrawalRef:Ref;withdrawAuthorizationRef:Ref;occurredAt:Instant};
type Engineering =
 {kind:'ITER';roundId:Key;candidateId:Key;candidateVersion:Key;digest:Digest;policyVersion:Key;
  reviewPackageRef:Ref;reviewPackageDigest:Digest;technicalManifestDigest:Digest|null;purpose:Key}
 |{kind:'ENG';candidateId:Key;candidateVersion:Key;technicalManifestDigest:Digest;
  reviewRoundRef:Ref;reviewPackageRef:Ref;reviewPackageDigest:Digest;policyVersion:Key;
  parentBaselineRef:Ref|null;purpose:Key}
 |{kind:'REL';baselineRef:Ref;purpose:Key;scopeRef:Ref;scopeDigest:Digest;permitPolicyRef:Ref}
 |{kind:'CHG';ecoRef:Ref;scopeRevision:Key;assessmentRef:Ref;assessmentDigest:Digest;
  signedScopeRows:{rowId:Key;scopeRef:Ref;scopeDigest:Digest}[];stage:'G2'|'G4'|'G5';
  targetBaselineRef:Ref|null;purpose:Key};
type Snapshot={schema:Key;canonicalBytesBase64:string;digest:Digest;immutableEvidenceRefs:Ref[]};
type SubmitCommand={schema:'oa.app/2.0';scope:Scope;commandId:Id;submissionId:Id;subject:Subject;
 policy:Policy;roundId:Key|null;replacesSubmissionId:Id|null;businessSubmittedRowVersion:RV;
 starterId:Id;submitAuthorizationRef:Ref;separationSubjectIds:Id[];snapshot:Snapshot;
 engineering:Engineering|null;reason:string;ownerOutboxId:Id;ownerFrozenAt:Instant};
type SubmissionAck={submissionId:Id;instanceId:Id|null;state:'DISPATCH_PENDING'|'RUNNING'|'SUSPENDED'|'START_UNKNOWN'|'BLOCKED';
 bindingRevisionId:Id|null;bindingTimelineRevisionId:Id|null;flowDefVersionId:Id|null;subject:Subject;policy:Policy;rowVersion:RV;errorCode:string|null;
 alias:{requestedSubmissionId:Id;canonicalSubmissionId:Id;aliasId:Id}|null};
type DecisionEnvelope={schema:'oa.app/2.0';scope:Scope;eventId:Id;decisionId:Id;streamId:Id;sequence:string;
 producerOwner:'Main Workflow';consumerOwner:Key;submissionId:Id;instanceId:Id;subject:Subject;policy:Policy;
 bindingRevisionId:Id;bindingTimelineRevisionId:Id;flowDefVersionId:Id;roundId:Key|null;engineering:Engineering|null;
 decision:'APPROVED'|'REJECTED'|'WITHDRAWN';decisionMode:'HUMAN'|'SYSTEM_POLICY'|'WITHDRAWAL';decidedAt:Instant;
 terminalActor:ActorEvidence;decisionEvidenceSetRef:Ref|null;decisionEvidenceDigest:Digest|null;
 satisfiedRequirementIds:Key[];reason:string|null;resultRef:Ref;payloadDigest:Digest};
type FactAck={kind:'PROCESSED';eventId:Id;decisionId:Id;submissionId:Id;payloadDigest:Digest;inboxId:Id;
 receiveState:'RECORDED'|'DUPLICATE'|'GAP'|'CONFLICT'|'STALE_RECEIPT';receivedAt:Instant;
 application:'NOT_APPLIED'|'PENDING'|'APPLIED'|'STALE'|'CONFLICT'|'BLOCKED'|'UNKNOWN';
 applicationReceiptId:Id|null;receiptStreamId:Id|null;receiptQueryRef:Link|null;errorCode:string|null};
type ApplicationReceipt={schema:'oa.app/2.0';scope:Scope;receiptId:Id;receiptStreamId:Id;receiptRevision:string;receiptEventId:Id;
 producerOwner:Key;submissionId:Id;instanceId:Id;decisionId:Id;decisionPayloadDigest:Digest;subject:Subject;
 action:Key;application:'APPLIED'|'STALE'|'CONFLICT'|'BLOCKED';outcomeCode:Key;
 appliedAt:Instant|null;actionActorId:Id|null;systemExecutionRef:Ref|null;
 businessResultRef:Ref|null;businessResultVersion:Key|null;currentSubjectRevision:Key;
 auditRef:Ref;previousReceiptId:Id|null;recordedAt:Instant;payloadDigest:Digest};
type Error={code:Key;messageKey:Key;correlationId:Id;retryable:boolean;
 fieldErrors:{field:string;code:Key}[];currentRowVersion:RV|null;resultQueryRef:Link|null};

type Seq=string; type EvidenceMode='REAL'|'DEMO';
interface PoApprovalEvent { eventId:Id; producerOwner:Key; submissionId:Id; instanceKey:Key;
 subjectKind:'PO_RELEASE'|'PO_CHANGE'|'PO_CANCEL'|'PO_CLOSE'; subjectId:Id;
 subjectBusinessRevision:Seq; subjectContentHash:string; policyRef:Ref;
 decision:'APPROVED'|'REJECTED'; decidedBy:Key; decidedAt:Instant; resultRef:Ref; evidenceMode:EvidenceMode; }

type Capabilities={schema:'oa.app/2.0';permissionEpoch:Key;
 bindingRead:boolean;bindingConfigure:boolean;callbackRead:boolean;callbackReplay:boolean;evidenceRead:boolean;
 supportedSchemas:('oa.app/2.0')[]};
type BindingOptions={businessTypes:{bizType:Key;owner:Key;subjectKinds:Key[];snapshotSchema:Key}[];
 flowVersions:{flowKey:Key;versionId:Id;version:string;status:'Published';headEnabled:boolean}[];asOf:Instant};
type CommandQuery={commandId:Id;state:'PENDING'|'COMPLETED'|'BLOCKED';targetType:'BINDING'|'SUBMISSION'|'TASK'|'DELIVERY';
 targetId:Id;resultRef:Ref|null;errorCode:Key|null;recordedAt:Instant};
type DeliveryView={eventId:Id;decisionId:Id;submissionId:Id;instanceId:Id;subject:Subject;payloadDigest:Digest;
 state:'PENDING'|'IN_FLIGHT'|'RECEIVED'|'UNKNOWN'|'RETRY'|'AUTH_BLOCKED'|'SCHEMA_BLOCKED'|'QUARANTINED'|'NEEDS_OPERATOR';
 attempts:number;receivedAt:Instant|null;nextAttemptAt:Instant|null;leaseUntil:Instant|null;claimEpoch:string;
 application:'NOT_APPLIED'|'PENDING'|'APPLIED'|'STALE'|'CONFLICT'|'BLOCKED'|'UNKNOWN';
 applicationReceiptId:Id|null;lastError:Error|null;rowVersion:RV;canReplay:boolean;disabledReasons:Key[]};
type TimelineItem={stepSeq:string;nodeId:Key;nodeName:string|null;taskId:Id;expectedHandlerDisplay:string;
 actualHandlerDisplay:string|null;onBehalfOfDisplay:string|null;roleKey:Key;status:'PENDING'|'APPROVED'|'REJECTED'|'WITHDRAWN'|'TRANSFERRED';
 comment:string|null;sentAt:Instant;handledAt:Instant|null;evidenceRef:Ref|null};
type SubmissionHistoryItem={submissionId:Id;subject:Subject;roundId:Key|null;replacesSubmissionId:Id|null;
 createdAt:Instant;state:'DISPATCH_PENDING'|'RUNNING'|'SUSPENDED'|'START_UNKNOWN'|'BLOCKED'|'DECIDED';
 decisionId:Id|null;applicationReceiptId:Id|null;historical:boolean};

type PendingReceipt={kind:'PENDING_VALIDATION';eventId:Id;decisionId:Id;submissionId:Id;
 payloadDigest:Digest;inboxId:Id;receivedAt:Instant;queryRef:Link};
type NotObserved={kind:'NOT_OBSERVED';eventId:Id;observedAt:Instant;queryRef:Link};
type ReceiveResult=PendingReceipt|FactAck|NotObserved;
type ReceiptIngestResult=
 {kind:'NOT_OBSERVED';receiptEventId:Id;observedAt:Instant;queryRef:Link}
 |{kind:'PENDING_GAP';receiptEventId:Id;receiptStreamId:Id;receiptId:Id;receiptRevision:string;
 payloadDigest:Digest;highestContinuousRevision:string;expectedNextRevision:string;queryRef:Link}
 |{kind:'RECORDED';receiptEventId:Id;receiptStreamId:Id;receiptId:Id;receiptRevision:string;
 payloadDigest:Digest;highestContinuousRevision:string;projectionReceiptId:Id|null;queryRef:Link};
type ReceiptChainPage={kind:'CHAIN';receiptStreamId:Id;instanceId:Id;subjectRevision:Key;applicationUnitId:Key;
 highestRevisionAtSnapshot:string;items:ApplicationReceipt[];nextCursor:string|null;snapshotToken:string};
type ReceiptChainResult=ReceiptChainPage|{kind:'NOT_OBSERVED';receiptStreamId:Id;observedAt:Instant};
type ApplicationResult={kind:'FOUND';receipt:ApplicationReceipt}
 |{kind:'NOT_APPLIED';receiptStreamId:Id;observedAt:Instant}
 |{kind:'PENDING';receiptStreamId:Id;commandId:Id;queryRef:Link};

type UserWithdrawRequest={commandId:Id;reason:string};
type WithdrawalActor=Extract<ActorEvidence,{kind:'SUBMITTER_WITHDRAWAL'}>;
type OwnerWithdrawalRecord={schema:'oa.app.withdrawal-fact/1.0';scope:Scope;
 owner:Key;ownerWithdrawalRef:BusinessRef;ownerCommandId:Id;userRequestDigest:Digest;
 submissionId:Id;subject:Subject;policyRef:BusinessRef;businessBeforeRowVersion:RV;
 businessAfterRowVersion:RV;withdrawnAt:Instant;actor:WithdrawalActor;reason:string};
type OwnerWithdrawCommand={schema:'oa.app.withdraw/2.0';scope:Scope;producerOwner:Key;
 commandId:Id;ownerOutboxId:Id;submissionId:Id;fact:OwnerWithdrawalRecord;factDigest:Digest};
type OwnerWithdrawContext={submissionId:Id;subject:Subject;policyRef:BusinessRef;instanceId:Id|null;
 workflowState:'RUNNING'|'SUSPENDED'|'APPROVED'|'REJECTED'|'WITHDRAWN'|'NOT_STARTED';
 submissionRowVersion:RV;canRelayWithdraw:boolean;disabledReasons:Key[]};
type OwnerWithdrawAck={commandId:Id;ownerCommandId:Id;submissionId:Id;ownerWithdrawalRef:BusinessRef;
 factDigest:Digest;state:'WITHDRAWN'|'BLOCKED'|'TERMINAL_CONFLICT';decisionId:Id|null;
 decisionRef:BusinessRef|null;errorCode:Key|null;queryRef:Link};
